"""Static, secret-free localhost review page. All data/actions need bearer auth."""

HTML = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>RiskCase · 风险调查工作台</title><style>
:root{color-scheme:light;--ink:#18333c;--muted:#577078;--line:#d7e1e0;--teal:#126b62;--paper:#f1f5f2}
*{box-sizing:border-box}body{margin:0;background:var(--paper);font:15px/1.65 system-ui,"Microsoft YaHei",sans-serif;color:var(--ink)}
header{background:#153c3d;color:#fff;padding:24px max(24px,calc((100vw - 1280px)/2))}header small{color:#c2dbd6;letter-spacing:2px}h1{font-size:28px;margin:4px 0}h2{font-size:19px;margin:0 0 14px}h3{font-size:16px}main{max-width:1328px;margin:auto;padding:24px;display:grid;grid-template-columns:360px 1fr;gap:20px}.card{background:white;border:1px solid var(--line);border-radius:12px;padding:22px;margin-bottom:18px}.muted,small{color:var(--muted)}label{display:block;margin:10px 0}input,select,textarea,button{font:inherit}input[type=password],select,textarea{width:100%;padding:10px;border:1px solid #abbfbd;border-radius:6px;background:white;color:var(--ink)}textarea{min-height:100px;resize:vertical}button{cursor:pointer;padding:9px 15px;border:1px solid var(--teal);border-radius:6px;color:white;background:var(--teal);margin:5px 6px 5px 0}button.secondary{background:white;color:var(--teal)}button.danger{background:#8f3a32;border-color:#8f3a32}button:disabled{opacity:.45;cursor:default}.badge{display:inline-block;padding:3px 10px;border-radius:20px;background:#e5f1eb;color:#1d6256;font-size:13px}.notice{padding:12px 15px;background:#fff5dc;border-left:3px solid #bc8b2b;margin:12px 0}.job{width:100%;text-align:left;background:white;color:var(--ink);border:1px solid var(--line);padding:10px}.job.active{border-color:var(--teal);background:#eaf5ef}.job span{display:block;font-size:12px;color:var(--muted)}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f6f8f6;padding:16px;border-radius:6px;font:14px/1.7 system-ui,"Microsoft YaHei",sans-serif}ul{padding-left:23px}.actions{margin-top:16px}#error{color:#9e3529}#login{max-width:660px;margin:24px auto}.hidden{display:none!important}.checks label{margin:5px 0}summary{cursor:pointer;color:var(--teal)}@media(max-width:850px){main{grid-template-columns:1fr;padding:14px}header{padding:18px}}
</style></head><body><header><small>RISKCASE / RESEARCH WORKBENCH</small><h1>支付预警调查与审阅</h1><div>让每条结论都能回到证据，让每次决定都有边界。</div></header>
<section id="login" class="card"><h2>连接本地工作台</h2><p class="muted">填写启动时生成的本地访问令牌。这里不需要模型 API Key。</p><label>本地访问令牌<input id="token" type="password" autocomplete="off"></label><button id="connect">连接</button><p id="loginError"></p></section>
<main id="workspace" class="hidden"><aside><section class="card"><h2>新建调查</h2><label>预警案例<select id="case"></select></label><p id="caseInfo" class="muted"></p><label>调查方式<select id="kind"><option value="mixed">直接选择检查项</option><option value="natural_v2">用一句话提出需求（v2）</option><option value="natural">自然语言旧版对照</option></select></label>
<div id="structured" class="checks"><label><input type="checkbox" value="frequency" checked> 此前1小时交易频次</label><label><input type="checkbox" value="amount" checked> 单笔正金额是否超过30天最大值</label><label><input type="checkbox" value="merchant" checked> 30天内是否出现过目标商户</label><label><input type="checkbox" value="count_share" checked> 7天 / 30天商户笔数集中度</label><label><input type="checkbox" value="amount_share" checked> 7天 / 30天商户正金额集中度</label></div>
<div id="natural" class="hidden"><label>你的问题<textarea id="question">查金额和新商户，不要查频次</textarea></label></div><label>执行模式<select id="mode"><option value="offline">免费离线流程验证</option><option value="live">真实模型（按本地预算计费）</option></select></label><button id="submit">提交调查</button><p class="muted">所有查询只读。结果不能认定欺诈、冻结账户或批准金融策略。</p></section>
<section class="card"><h2>最近任务</h2><div id="jobs"></div><button id="refresh" class="secondary">刷新</button></section><button id="logout" class="secondary">断开连接</button></aside>
<article><section class="card"><h2 id="title">从一条预警开始</h2><div id="state"></div><p id="error"></p><div id="content"><p>选择左侧案例和核查范围，提交后查看证据与报告。</p><div class="notice">自建案例用于演示流程；IBM数据案例来自合成交易。均不能代表真实支付风控效果。</div></div><div id="actions" class="actions"></div></section><section class="card"><h2>处理轨迹</h2><div id="events" class="muted">选择任务后显示。</div></section></article></main>
<script>
"use strict";
const $=id=>document.getElementById(id), states={queued:"等待处理",running:"正在调查",awaiting_plan_confirmation:"请确认调查范围",awaiting_review:"报告等待审阅",needs_clarification:"需要明确问题",out_of_scope:"超出支持范围",completed:"报告已审阅",rejected:"已拒绝",cancelled:"已取消",cancel_requested:"正在取消",blocked:"已停止，请检查运行记录",failed:"本次调查失败"};
const checkLabels={frequency:"1小时频次",amount:"单笔金额",merchant:"新商户",count_share:"笔数集中度",amount_share:"正金额集中度"},caseLabels={"new-pattern":"金额与商户变化（自建）","ordinary-pattern":"历史行为反证（自建）","missing-history":"历史资料不足（自建）"};
let token=sessionStorage.getItem("riskcase-local-token")||"",current=null,details={},timer=null,viewSequence=0,pendingSubmission=null;
async function api(path,options={}){const headers={Authorization:"Bearer "+token,...options.headers};if(options.body)headers["Content-Type"]="application/json";const r=await fetch(path,{...options,headers,cache:"no-store"});if(!r.ok){let b={};try{b=await r.json()}catch{}throw Error(b.error||"请求未完成（"+r.status+"）")}return r}
const key=()=>"ui-"+crypto.randomUUID();function text(parent,tag,value,cls){const n=document.createElement(tag);n.textContent=value;if(cls)n.className=cls;parent.append(n);return n}
async function connect(){try{token=$("token").value.trim()||token;const health=await(await api("/health")).json();$("login").classList.add("hidden");$("workspace").classList.remove("hidden");sessionStorage.setItem("riskcase-local-token",token);const cases=await(await api("/cases/details")).json();$("case").replaceChildren();for(const row of cases.cases){details[row.case_id]=row;const o=document.createElement("option");o.value=row.case_id;o.textContent=caseLabels[row.case_id]||row.case_id;$("case").append(o)}if(details["new-pattern"])$("case").value="new-pattern";$("mode").options[1].disabled=!health.live_enabled;caseInfo();await refresh();if(!timer)timer=setInterval(()=>refresh().catch(showError),3000)}catch(e){$("loginError").textContent="连接失败："+e.message}}
function caseInfo(){const d=details[$("case").value];$("caseInfo").textContent=d?(d.data_kind==="self_authored_fixture"?"自建演示案例，分数为手工设置。":"IBM合成数据案例，模型分数用于排序。")+" 截止："+d.cutoff:""}
function showError(e){$("error").textContent=e.message}
async function refresh(){const rows=(await(await api("/jobs?limit=25")).json()).jobs;$("jobs").replaceChildren();for(const j of rows){const title=j.task_type==="mixed"?j.question_text.split(" / ").map(k=>checkLabels[k]||k).join("、"):j.question_text||j.case_id;const b=text($("jobs"),"button",title,"job"+(j.id===current?" active":""));text(b,"span",(states[j.state]||j.state)+" · "+j.id.slice(-8));b.onclick=()=>select(j.id).catch(showError)}if(current)await select(current)}
async function select(id){current=id;const sequence=++viewSequence;$("error").textContent="";const j=await(await api("/jobs/"+id)).json();if(sequence!==viewSequence||current!==id)return;$("title").textContent="调查任务 · "+id.slice(-8);$("state").replaceChildren();text($("state"),"span",states[j.state]||j.state,"badge");$("actions").replaceChildren();$("content").replaceChildren();let plan=null;
if(j.result){if(j.state==="awaiting_plan_confirmation"){plan=await(await api("/jobs/"+id+"/artifacts/plan.json")).json();if(sequence!==viewSequence||current!==id)return;text($("content"),"p","请核对以下具体口径。确认后才会取证；这不批准任何金融规则。");const ul=document.createElement("ul");for(const label of plan.scope_labels)text(ul,"li",label);$("content").append(ul);text($("content"),"p","集中度两窗口最少各10笔；近7天包含在30天内。","muted");action("确认只读调查范围",()=>post(j.id,"confirm-plan",{expected_version:j.version,result_hash:j.result_hash,plan_hash:j.result.plan_hash,decision:"confirm_plan"}));action("拒绝这个范围",()=>post(j.id,"confirm-plan",{expected_version:j.version,result_hash:j.result_hash,plan_hash:j.result.plan_hash,decision:"reject_plan"}),"secondary")}
else if(["awaiting_review","completed","rejected"].includes(j.state)){try{const report=await(await api("/jobs/"+id+"/artifacts/report.md")).text();if(sequence!==viewSequence||current!==id)return;text($("content"),"pre",report)}catch(e){if(sequence!==viewSequence||current!==id)return;showError(e)}if(sequence!==viewSequence||current!==id)return;if(j.state==="awaiting_review"){action("已核对，接受报告",()=>post(j.id,"review",{expected_version:j.version,result_hash:j.result_hash,decision:"accept_report"}));action("拒绝报告",()=>post(j.id,"review",{expected_version:j.version,result_hash:j.result_hash,decision:"reject_report"}),"secondary")}}
else if(j.state==="needs_clarification")text($("content"),"p","请明确要查频次、单笔金额、新商户，还是按笔数/正金额衡量集中度，然后重新提交。系统没有为本次问题执行调查查询。");else if(j.state==="out_of_scope")text($("content"),"p","本次请求不在已支持的只读检查范围内。请勿请求认定欺诈、账户处置、未支持窗口或其他用户资料。")}
if(["queued","running","awaiting_plan_confirmation","cancel_requested"].includes(j.state))action("取消任务",()=>post(j.id,"cancel",{}),"danger");if(j.reason)text($("content"),"p","停止原因："+j.reason,"notice");if(!$("content").childElementCount)text($("content"),"p","工作进程处理后会在此显示下一步。");const es=await(await api("/jobs/"+id+"/events")).json();if(sequence!==viewSequence||current!==id)return;$("events").replaceChildren();for(const e of es.events)text($("events"),"div",new Date(e.at*1000).toLocaleTimeString()+" · "+({submitted:"任务已保存",claimed:"开始处理",call_intent_saved:"记录模型请求",response_saved:"模型响应已保存",response_replayed:"回放已保存响应",scope_reviewed:"调查范围已确认或拒绝",finished:"处理阶段结束",report_reviewed:"报告已审阅",cancellation_requested:"收到取消请求",lease_expired:"工作进程中断后重新检查"}[e.kind]||e.kind));}
function action(label,fn,cls){const b=text($("actions"),"button",label,cls);b.onclick=()=>{b.disabled=true;Promise.resolve(fn()).catch(showError).finally(()=>b.disabled=false)}}
async function post(identity,path,body){await api("/jobs/"+identity+"/"+path,{method:"POST",headers:{"Idempotency-Key":key()},body:JSON.stringify(body)});await refresh()}
$("connect").onclick=connect;$("case").onchange=caseInfo;$("refresh").onclick=()=>refresh().catch(showError);$("kind").onchange=()=>{const natural=$("kind").value!=="mixed";$("structured").classList.toggle("hidden",natural);$("natural").classList.toggle("hidden",!natural)};
$("submit").onclick=async()=>{try{$("submit").disabled=true;const type=$("kind").value,question=type==="mixed"?{checks:[...document.querySelectorAll("#structured input:checked")].map(e=>e.value),min_records:10}:{text:$("question").value};const body=JSON.stringify({case_id:$("case").value,task_type:type,mode:$("mode").value,question});if(!pendingSubmission||pendingSubmission.body!==body)pendingSubmission={body,key:key()};const j=await(await api("/jobs",{method:"POST",headers:{"Idempotency-Key":pendingSubmission.key},body})).json();pendingSubmission=null;current=j.id;await refresh()}catch(e){showError(e)}finally{$("submit").disabled=false}};
$("logout").onclick=()=>{sessionStorage.removeItem("riskcase-local-token");token="";clearInterval(timer);timer=null;location.reload()};if(token)connect();
</script></body></html>'''
